import React from 'react';
import type { Wall, Door } from '../../core/types';

interface Props {
  wall: Wall;
    door: Door;
      color?: string;
        openAngleDeg?: number;
        }

        export const Door3D: React.FC<Props> = ({
          wall,
            door,
              color = '#8B5A2B',
                openAngleDeg = 80,
                }) => {
                  const dx = wall.end.x - wall.start.x;
                    const dy = wall.end.y - wall.start.y;
                      const len = Math.hypot(dx, dy) || 1;

                        const cx = door.center?.x ?? (wall.start.x + ((door.position + door.width / 2) / len) * dx);
                          const cy = door.center?.y ?? (wall.start.y + ((door.position + door.width / 2) / len) * dy);

                            const rot = door.rotation ?? Math.atan2(dy, dx);
                              const doorType = door.doorType ?? 'regular';

                                // ======================================================
                                  // 🏪 باب محل — Roll-up shutter (رمادي بدون صندوق/فاصل)
                                    // ======================================================
                                      if (doorType === 'shop') {
                                          const SLAT_COUNT = Math.max(15, Math.floor(door.height / 0.06));
                                              const slatH = door.height / SLAT_COUNT;
                                                  const slatColor = '#9a9a9a';         // ✅ رمادي
                                                      const slatDark = '#7a7a7a';          // ✅ ظل رمادي غامق

                                                          return (
                                                                <group position={[cx, 0, cy]} rotation={[0, -rot, 0]}>
                                                                        {/* الشرائح الأفقية المتراصة */}
                                                                                {Array.from({ length: SLAT_COUNT }).map((_, i) => (
                                                                                          <mesh key={i} position={[0, slatH * (i + 0.5), 0]}>
                                                                                                      <boxGeometry args={[door.width, slatH * 0.92, 0.05]} />
                                                                                                                  <meshStandardMaterial color={slatColor} metalness={0.35} roughness={0.5} />
                                                                                                                            </mesh>
                                                                                                                                    ))}

                                                                                                                                            {/* قضيب سفلي (لون غامق - علامة الإغلاق) */}
                                                                                                                                                    <mesh position={[0, slatH * 0.4, 0]}>
                                                                                                                                                              <boxGeometry args={[door.width + 0.05, 0.06, 0.06]} />
                                                                                                                                                                        <meshStandardMaterial color={slatDark} metalness={0.5} roughness={0.4} />
                                                                                                                                                                                </mesh>

                                                                                                                                                                                        {/* ✅ حذف: صندوق الرول العلوي */}
                                                                                                                                                                                                {/* ✅ حذف: الخط الرأسي في المنتصف */}
                                                                                                                                                                                                      </group>
                                                                                                                                                                                                          );
                                                                                                                                                                                                            }

                                                                                                                                                                                                              // ======================================================
                                                                                                                                                                                                                // 🚪 باب رئيسي — Laser Cut Metal (نقوش ذهبية بارزة)
                                                                                                                                                                                                                  // ======================================================
                                                                                                                                                                                                                    if (doorType === 'main') {
                                                                                                                                                                                                                        const metalColor = '#1f1f1f';
                                                                                                                                                                                                                            const goldColor = '#c9a24a';

                                                                                                                                                                                                                                // شبكة النقوش (5 أعمدة × 4 صفوف)
                                                                                                                                                                                                                                    const COLS = 5;
                                                                                                                                                                                                                                        const ROWS = 4;
                                                                                                                                                                                                                                            const innerW = door.width * 0.75;
                                                                                                                                                                                                                                                const innerH = door.height * 0.55;
                                                                                                                                                                                                                                                    const cellW = innerW / COLS;
                                                                                                                                                                                                                                                        const cellH = innerH / ROWS;

                                                                                                                                                                                                                                                            // ✅ سماكة اللوح الأمامي وموضع النقوش (خارج السطح بوضوح)
                                                                                                                                                                                                                                                                const BASE_THICKNESS = 0.06;
                                                                                                                                                                                                                                                                    const BASE_FRONT_Z = BASE_THICKNESS / 2;    // = 0.03
                                                                                                                                                                                                                                                                        const DECOR_Z = BASE_FRONT_Z + 0.02;        // = 0.05 (بارزة 2 سم)
                                                                                                                                                                                                                                                                            const FRAME_Z = BASE_FRONT_Z + 0.015;       // = 0.045

                                                                                                                                                                                                                                                                                return (
                                                                                                                                                                                                                                                                                      <group position={[cx, 0, cy]} rotation={[0, -rot, 0]}>
                                                                                                                                                                                                                                                                                              {/* اللوح الأساسي (معدني داكن) */}
                                                                                                                                                                                                                                                                                                      <mesh position={[0, door.height / 2, 0]}>
                                                                                                                                                                                                                                                                                                                <boxGeometry args={[door.width, door.height, BASE_THICKNESS]} />
                                                                                                                                                                                                                                                                                                                          <meshStandardMaterial
                                                                                                                                                                                                                                                                                                                                      color={metalColor}
                                                                                                                                                                                                                                                                                                                                                  metalness={0.85}
                                                                                                                                                                                                                                                                                                                                                              roughness={0.2}
                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                </mesh>

                                                                                                                                                                                                                                                                                                                                                                                        {/* ✅ شبكة النقوش الذهبية (بارزة بوضوح) */}
                                                                                                                                                                                                                                                                                                                                                                                                {Array.from({ length: COLS * ROWS }).map((_, idx) => {
                                                                                                                                                                                                                                                                                                                                                                                                          const c = idx % COLS;
                                                                                                                                                                                                                                                                                                                                                                                                                    const r = Math.floor(idx / COLS);
                                                                                                                                                                                                                                                                                                                                                                                                                              const x = -innerW / 2 + cellW * (c + 0.5);
                                                                                                                                                                                                                                                                                                                                                                                                                                        const y = door.height * 0.55 + cellH * (r - ROWS / 2 + 0.5);
                                                                                                                                                                                                                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                              <mesh key={`decor-${idx}`} position={[x, y, DECOR_Z]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <boxGeometry args={[cellW * 0.75, cellH * 0.75, 0.025]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <meshStandardMaterial
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          color={goldColor}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          metalness={0.95}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          roughness={0.1}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      })}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {/* ✅ إطار ذهبي علوي عريض */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <mesh position={[0, door.height * 0.9, FRAME_Z]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <boxGeometry args={[door.width * 0.9, 0.06, 0.03]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <meshStandardMaterial
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      color={goldColor}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  metalness={0.95}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              roughness={0.1}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </mesh>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {/* ✅ إطار ذهبي سفلي عريض */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <mesh position={[0, door.height * 0.1, FRAME_Z]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <boxGeometry args={[door.width * 0.9, 0.06, 0.03]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <meshStandardMaterial
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                color={goldColor}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            metalness={0.95}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        roughness={0.1}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </mesh>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {/* ✅ إطاران رأسيان (يمين ويسار) */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <mesh position={[-door.width * 0.42, door.height / 2, FRAME_Z]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <boxGeometry args={[0.04, door.height * 0.85, 0.03]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <meshStandardMaterial color={goldColor} metalness={0.95} roughness={0.1} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <mesh position={[door.width * 0.42, door.height / 2, FRAME_Z]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <boxGeometry args={[0.04, door.height * 0.85, 0.03]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <meshStandardMaterial color={goldColor} metalness={0.95} roughness={0.1} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </mesh>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {/* ✅ مقبض فضي طويل في المنتصف */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <mesh position={[0, door.height * 0.5, DECOR_Z + 0.02]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <boxGeometry args={[0.035, door.height * 0.25, 0.04]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <meshStandardMaterial color="#c0c0c0" metalness={1.0} roughness={0.15} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </group>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ======================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // 🚪 باب عادي — Swing (كما قبل)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ======================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const cosR = Math.cos(rot);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const sinR = Math.sin(rot);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const hxLocal = door.hinge === 'start' ? -door.width / 2 : door.width / 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const closedSign = door.hinge === 'start' ? 1 : -1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const swingSign = door.swing || 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const thetaSigned = (openAngleDeg * Math.PI / 180) * closedSign * swingSign;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const dirWorldX = closedSign * Math.cos(thetaSigned + rot);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const dirWorldY = closedSign * Math.sin(thetaSigned + rot);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const hingeWorldX = cx + hxLocal * cosR;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const hingeWorldY = cy + hxLocal * sinR;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const leafCenterX = hingeWorldX + dirWorldX * (door.width / 2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const leafCenterY = hingeWorldY + dirWorldY * (door.width / 2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const leafRotY = Math.atan2(-dirWorldY, dirWorldX);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const doorThickness = 0.05;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <group>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <mesh
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        position={[leafCenterX, door.height / 2, leafCenterY]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                rotation={[0, leafRotY, 0]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <boxGeometry args={[door.width, door.height, doorThickness]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <meshStandardMaterial color={color} roughness={0.7} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </mesh>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <mesh
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          position={[
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    hingeWorldX + dirWorldX * door.width * 0.88,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              door.height * 0.5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        hingeWorldY + dirWorldY * door.width * 0.88,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <sphereGeometry args={[0.04, 12, 12]} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <meshStandardMaterial color="#FFD700" metalness={0.85} roughness={0.15} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </group>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  };